def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timedelta, timezone
    if tz:
        tz = timezone(tz / (24 * 3600 * 10**9))
    return datetime(1970, 1, 1, tzinfo=tz) + timedelta(nanoseconds / 10 ** 9)

