def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    converted_params = []
    placeholder = '?' if isinstance(sql, bytes) else ':'

    for params in many_params:
        if isinstance(params, dict):
            converted_params.append({k: v for k, v in params.items() if k.startswith(placeholder)})
        else:
            converted_params.append([v for v in params if isinstance(v, (int, float, str))])

    # Replace placeholders in the SQL query with out-style placeholders
    formatted_sql = sql.replace('? ', placeholder).replace('?,', placeholder).replace('?', placeholder)

    return formatted_sql, converted_params

