def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'algorithm' not in fixity:
        raise ValueError("Fixity block must contain 'algorithm' key")

    if 'tree' not in fixity:
        raise ValueError("Fixity block must contain 'tree' key")

    allowed_algorithms = {'sha256', 'md5'}
    if fixity['algorithm'] not in allowed_algorithms:
        raise ValueError(f"Unsupported fixity algorithm: {fixity['algorithm']}")

    for file_path, hash_value in fixity['tree'].items():
        if file_path not in manifest_files:
            raise ValueError(f"Referenced file '{file_path}' not found in manifest")

