def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """

    def format_value(value):
        if isinstance(value, dict):
            return "{\n" + "\n".join(f"{indent + 2*' '}{k}: {format_value(v)}" for k, v in value.items()) + "\n" + f"{indent*' '}}"
        elif isinstance(value, list):
            return "[\n" + "\n".join(f"{indent + 2*' '}{format_value(v)}" for v in value) + "\n" + f"{indent*' '}]"
        elif isinstance(value, (int, float, str)):
            return str(value)
        else:
            return "<{type}>".format(type=type(value).__name__)

    return format_value(self, indent)

