    """
    Call the given command(s).
    """
    for command in commands:
        full_command = [command] + args
        try:
            output = subprocess.check_output(full_command, cwd=cwd, env=env, stderr=subprocess.STDOUT if not hide_stderr else subprocess.DEVNULL)
            if verbose:
                print(output.decode())
            return output
        except subprocess.CalledProcessError as e:
            error_output = e.output.decode()
            if verbose:
                print(error_output)
            raise Exception(f"Command failed: {full_command}\nError: {error_output}")

