def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    from zope.interface import implementedBy
    implementedBy_candidate = implementedBy(candidate)
    iface_set = set(iface __subclasses__())
    implementedBy_candidate_set = set(implementedBy_candidate __subclasses__())

    if tentative:
        return iface_set.issubset(implementedBy_candidate_set)
    else:
        return iface_set == implementedBy_candidate_set

