def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    # Add attributes to links
    def link_attrs(url):
        return ' target="_blank"'

    # Linkify textual links
    def linkify(match):
        url = match.group(0)
        if 'http' in url or 'www' in url:
            return f'<a href="{url}"{link_attrs(url)}>{url}</a>'
        else:
            return f'<a href="{url}"{link_attrs(url)}>{url}</a>'

    import re
    result = re.sub(r'(https?://[^\s]+|www\.[^\s]+)', linkify, text)
    return result

