def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    for extra_var in extra_vars:
        key = next(iter(extra_var))
        if key in vars_dict:
            if isinstance(vars_dict[key], dict) and isinstance(extra_var[key], dict):
                merge_extra_vars(vars_dict[key], extra_var[key])
            else:
                vars_dict[key] = extra_var[key]
        else:
            vars_dict[key] = extra_var[key]

    return vars_dict

